using CADability.GeoObject;
using System.Runtime.CompilerServices;
using IOPath = System.IO.Path;

namespace CADability.Tests
{
    /// <summary>
    /// Placement of assembly occurrences in the STEP import. The files in Files/Step/Assembly are generated by
    /// make_assemblies.py: a box (0,0,0)-(10,20,40) placed in an assembly. They vary the order of rep_1/rep_2 in the
    /// REPRESENTATION_RELATIONSHIP_WITH_TRANSFORMATION (child first like Inventor, parent first like SolidWorks),
    /// the placement inside the child representation (identity or not), the order of the items in the
    /// ITEM_DEFINED_TRANSFORMATION, and the number of assembly levels. The placement must always be
    /// "parent placement * inverse(child placement)", independent of how the file writes it.
    /// </summary>
    [TestClass]
    public class StepAssemblyTests
    {
        private static string StepFile(string name, [CallerFilePath] string thisFile = "")
            => IOPath.Combine(IOPath.GetDirectoryName(thisFile)!, "Files", "Step", "Assembly", name);

        private static IEnumerable<Solid> Solids(GeoObjectList list)
        {
            foreach (IGeoObject go in list)
            {
                if (go is Solid s) yield return s;
                else if (go is Block b) foreach (Solid bs in Solids(b.Children)) yield return bs;
            }
        }

        [DataTestMethod]
        [DataRow("box_child_first_ident_p1.stp", 80.0, 0.0, 0.0, 100.0, 10.0, 40.0)]
        [DataRow("box_child_first_ident_p2.stp", 0.0, 30.0, 25.0, 40.0, 50.0, 35.0)]
        [DataRow("box_child_first_ident_swapped_p1.stp", 80.0, 0.0, 0.0, 100.0, 10.0, 40.0)]
        [DataRow("box_child_first_ident_swapped_p2.stp", 0.0, 30.0, 25.0, 40.0, 50.0, 35.0)]
        [DataRow("box_child_first_offset_p1.stp", 95.0, -5.0, -5.0, 105.0, 15.0, 35.0)]
        [DataRow("box_child_first_offset_p2.stp", -5.0, 45.0, 20.0, 35.0, 55.0, 40.0)]
        [DataRow("box_child_first_offset_swapped_p1.stp", 95.0, -5.0, -5.0, 105.0, 15.0, 35.0)]
        [DataRow("box_child_first_offset_swapped_p2.stp", -5.0, 45.0, 20.0, 35.0, 55.0, 40.0)]
        [DataRow("box_parent_first_ident_p1.stp", 80.0, 0.0, 0.0, 100.0, 10.0, 40.0)]
        [DataRow("box_parent_first_ident_p2.stp", 0.0, 30.0, 25.0, 40.0, 50.0, 35.0)]
        [DataRow("box_parent_first_ident_swapped_p1.stp", 80.0, 0.0, 0.0, 100.0, 10.0, 40.0)]
        [DataRow("box_parent_first_ident_swapped_p2.stp", 0.0, 30.0, 25.0, 40.0, 50.0, 35.0)]
        [DataRow("box_parent_first_offset_p1.stp", 95.0, -5.0, -5.0, 105.0, 15.0, 35.0)]
        [DataRow("box_parent_first_offset_p2.stp", -5.0, 45.0, 20.0, 35.0, 55.0, 40.0)]
        [DataRow("box_parent_first_offset_swapped_p1.stp", 95.0, -5.0, -5.0, 105.0, 15.0, 35.0)]
        [DataRow("box_parent_first_offset_swapped_p2.stp", -5.0, 45.0, 20.0, 35.0, 55.0, 40.0)]
        [DataRow("box_two_levels.stp", 58.0, -35.0, -2.0, 98.0, -15.0, 8.0)]
        public void an_occurrence_is_placed_by_parent_placement_times_inverse_child_placement(string file,
            double xmin, double ymin, double zmin, double xmax, double ymax, double zmax)
        {
            AssertImportedBox(file, xmin, ymin, zmin, xmax, ymax, zmax);
        }

        /// <summary>
        /// Every representation has the length unit of its own context: the geometry and the placements are converted
        /// to millimetres per representation, also when the part, the assemblies or a mapped representation use
        /// different units. The files write the same millimetre geometry in inch, metre, "INCH = 0.0254 METRE" and
        /// "MILLIMETRE = 0.001 METRE".
        /// </summary>
        [DataTestMethod]
        [DataRow("box_unit_inch.stp", 0.0, 0.0, 0.0, 10.0, 20.0, 40.0)]
        [DataRow("box_unit_m.stp", 0.0, 0.0, 0.0, 10.0, 20.0, 40.0)]
        [DataRow("box_unit_inch_m.stp", 0.0, 0.0, 0.0, 10.0, 20.0, 40.0)]
        [DataRow("box_unit_mm_m.stp", 0.0, 0.0, 0.0, 10.0, 20.0, 40.0)]
        [DataRow("box_child_first_offset_p1_part_inch.stp", 95.0, -5.0, -5.0, 105.0, 15.0, 35.0)]
        [DataRow("box_parent_first_offset_p2_assembly_inch.stp", -5.0, 45.0, 20.0, 35.0, 55.0, 40.0)]
        [DataRow("box_two_levels_units.stp", 58.0, -35.0, -2.0, 98.0, -15.0, 8.0)]
        [DataRow("box_mapped.stp", 95.0, -5.0, -5.0, 105.0, 15.0, 35.0)]
        [DataRow("box_mapped_inch.stp", 95.0, -5.0, -5.0, 105.0, 15.0, 35.0)]
        [DataRow("box_mapped_outer_m.stp", 95.0, -5.0, -5.0, 105.0, 15.0, 35.0)]
        public void each_representation_is_converted_to_millimetres_by_its_own_units(string file,
            double xmin, double ymin, double zmin, double xmax, double ymax, double zmax)
        {
            AssertImportedBox(file, xmin, ymin, zmin, xmax, ymax, zmax);
        }

        /// <summary>
        /// A CARTESIAN_TRANSFORMATION_OPERATOR_3D maps rep_1 into rep_2, its local origin is given in the units of rep_2. The
        /// axes are normalized as in base_axis (a missing axis2 is the cross product of axis3 and axis1), the scale applies
        /// to the mapped geometry: as the target of a mapped item the box is placed twice as large.
        /// </summary>
        [DataTestMethod]
        [DataRow("box_cto_child_first_offset_p1_assembly_inch.stp", 95.0, -5.0, -5.0, 105.0, 15.0, 35.0)]
        [DataRow("box_cto_parent_first_offset_p2_part_inch.stp", -5.0, 45.0, 20.0, 35.0, 55.0, 40.0)]
        [DataRow("box_mapped_cto_scaled.stp", 90.0, -10.0, -10.0, 110.0, 30.0, 70.0)]
        public void a_cartesian_transformation_operator_places_the_occurrence(string file,
            double xmin, double ymin, double zmin, double xmax, double ymax, double zmax)
        {
            AssertImportedBox(file, xmin, ymin, zmin, xmax, ymax, zmax);
        }

        /// <summary>
        /// The parameters of a trimmed circle are given in the angle unit (here degree) of its representation. A
        /// presentation representation, which styles the arc and has a plain REPRESENTATION_CONTEXT without units, must
        /// not replace these units.
        /// </summary>
        [TestMethod]
        public void a_styled_arc_is_trimmed_in_the_angle_unit_of_its_own_representation()
        {
            ImportStep import = new ImportStep();
            GeoObjectList imported = import.Read(StepFile("arc_degree_styled.stp"));
            BoundingBox ext = BoundingBox.EmptyBoundingBox;
            foreach (IGeoObject go in imported) ext.MinMax(go.GetBoundingCube());
            const double eps = 1e-5;
            Assert.AreEqual(3.872983, ext.Xmin, eps, "xmin");
            Assert.AreEqual(3.872983, ext.Ymin, eps, "ymin");
            Assert.AreEqual(7.0, ext.Xmax, eps, "xmax");
            Assert.AreEqual(7.0, ext.Ymax, eps, "ymax");
        }

        /// <summary>
        /// The shape of a product are the items of its own representations. When the representations of several products
        /// share one representation context, every occurrence must still get only the shape of its own part: the box
        /// is placed twice, the cube once.
        /// </summary>
        [TestMethod]
        public void each_occurrence_gets_only_the_shape_of_its_own_part_when_parts_share_a_context()
        {
            ImportStep import = new ImportStep();
            GeoObjectList imported = import.Read(StepFile("shared_context.stp"));
            AssertSolidExtents(Solids(imported).ToList(),
                new[] { 0.0, 30.0, 25.0, 40.0, 50.0, 35.0 },
                new[] { 80.0, 0.0, 0.0, 100.0, 10.0, 40.0 },
                new[] { 200.0, 0.0, 0.0, 205.0, 5.0, 5.0 });
        }

        /// <summary>
        /// With the hierarchy as blocks, the root product is one block named after the product, containing the placed parts.
        /// </summary>
        [TestMethod]
        public void the_root_product_becomes_one_block_with_the_placed_parts()
        {
            ImportStep import = new ImportStep();
            import.HierarchyToBlocks = true;
            GeoObjectList imported = import.Read(StepFile("shared_context.stp"));
            Assert.AreEqual(1, imported.Count, "one root");
            Block top = imported[0] as Block;
            Assert.IsNotNull(top, "the root is a block");
            Assert.AreEqual("Top", top.Name);
            Assert.AreEqual(3, top.NumChildren, "three occurrences");
            AssertSolidExtents(Solids(top.Children).ToList(),
                new[] { 0.0, 30.0, 25.0, 40.0, 50.0, 35.0 },
                new[] { 80.0, 0.0, 0.0, 100.0, 10.0, 40.0 },
                new[] { 200.0, 0.0, 0.0, 205.0, 5.0, 5.0 });
        }

        /// <summary>
        /// An occurrence of a part with several objects becomes a block. It is named after the instance name of the
        /// NEXT_ASSEMBLY_USAGE_OCCURRENCE when that extends the product name ("Pair:1"), otherwise after the product (the
        /// generic "NAUO2"). An occurrence of a single solid is not put into a block, the solid has the product name.
        /// </summary>
        [TestMethod]
        public void occurrences_are_named_after_their_instance_name_or_the_product()
        {
            ImportStep import = new ImportStep();
            import.HierarchyToBlocks = true;
            GeoObjectList imported = import.Read(StepFile("occurrence_names.stp"));
            Block top = imported.Single() as Block;
            Assert.IsNotNull(top, "the root is a block");
            Assert.AreEqual("Top", top.Name);
            List<string> names = top.Children.Select(go => go is Block b ? "Block " + b.Name : go is Solid s ? "Solid " + s.Name : go.GetType().Name).ToList();
            CollectionAssert.AreEqual(new[] { "Block Pair:1", "Block Pair", "Solid Box" }, names);
            Assert.AreEqual(5, Solids(top.Children).Count(), "two solids per pair, one box");
        }

        /// <summary>
        /// An exception while creating one item (here an ellipse with zero semi axes in a wireframe of the part) does not
        /// abort the import: the item is reported in <see cref="ImportStep.Problems"/>, the box is still imported.
        /// </summary>
        [TestMethod]
        public void an_item_which_cannot_be_created_is_reported_and_the_rest_is_imported()
        {
            ImportStep import = new ImportStep();
            GeoObjectList imported = import.Read(StepFile("broken_item.stp"));
            AssertSolidExtents(Solids(imported).ToList(), new[] { 0.0, 0.0, 0.0, 10.0, 20.0, 40.0 });
            Assert.IsTrue(import.Problems.Values.Any(p => p.StartsWith("exception on ")), "the exception is reported: " + string.Join("; ", import.Problems.Values));
        }

        private static void AssertSolidExtents(List<Solid> solids, params double[][] expected)
        {
            Assert.AreEqual(expected.Length, solids.Count, "number of solids");
            List<BoundingBox> found = solids.Select(s => s.GetBoundingCube()).OrderBy(b => b.Xmin).ThenBy(b => b.Ymin).ToList();
            double[][] sorted = expected.OrderBy(e => e[0]).ThenBy(e => e[1]).ToArray();
            const double eps = 1e-6;
            for (int i = 0; i < sorted.Length; i++)
            {
                double[] e = sorted[i];
                BoundingBox b = found[i];
                double[] actual = { b.Xmin, b.Ymin, b.Zmin, b.Xmax, b.Ymax, b.Zmax };
                for (int k = 0; k < 6; k++) Assert.AreEqual(e[k], actual[k], eps, $"solid {i}, value {k}");
            }
        }

        private static void AssertImportedBox(string file, double xmin, double ymin, double zmin, double xmax, double ymax, double zmax)
        {
            ImportStep import = new ImportStep();
            GeoObjectList imported = import.Read(StepFile(file));
            Solid box = Solids(imported).Single();
            BoundingBox ext = box.GetBoundingCube();
            const double eps = 1e-6;
            Assert.AreEqual(xmin, ext.Xmin, eps, "xmin");
            Assert.AreEqual(ymin, ext.Ymin, eps, "ymin");
            Assert.AreEqual(zmin, ext.Zmin, eps, "zmin");
            Assert.AreEqual(xmax, ext.Xmax, eps, "xmax");
            Assert.AreEqual(ymax, ext.Ymax, eps, "ymax");
            Assert.AreEqual(zmax, ext.Zmax, eps, "zmax");
        }
    }
}
